using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.SpectralGraph;
internal sealed class IdealIntersectionObstructionsDocument : IScribeDocumentDefinition
{
    private const string Prefix="D5/S3/Combinatorics/SpectralGraph/IdealIntersectionObstructions.";
    private static readonly LibraryNoteRef Source=LibraryNoteRef.Create("D5/L/GraphInvariants/idealintersection2026sixsupport");
    public DocumentDefinition Create()=>DocumentDefinition.Create(ScribeNode.Create(
        "Actual ideal-intersection graphs and uniform higher-prime Laplacian obstructions.",
        H("IdealIntersectionObstructions"),Blocks(
            Paragraph(Text("The public mathematical input is unit-exponent.tex at immutable revision b93becea662a746badeadba42fdc3d3eb3db9382. General endpoint arguments follow the completed mathematical note supplied 2026-11-02. The formal proofs and this exposition are independently authored; no priority claim follows.")),
            Node("HasActualEigenvalue","Spectrum of the actual finite ideal graph","This predicate uses the Laplacian on the actual nonzero proper ideals. Its finite structure comes from the finite underlying ring; no quotient or desired spectral bridge is assumed in the definition.",DescribeRole.Definition),
            Node("ActualLaplacianIntegral","Actual Laplacian integrality","Every real Laplacian eigenvalue of the actual ideal graph is an integer. Symmetry of the real Laplacian gives the usual spectral interpretation.",DescribeRole.Definition),
            Node("actual_eigenvalue_of_support","Actual graph spectral reflection","A nonzero support-model complement eigenvector with total sum zero yields the actual ideal-graph eigenvalue V minus the complement eigenvalue. This uses the proved graph isomorphism and the identity L(G)+L(complement G)=V I-J. The intermediate complement eigenvalue is allowed to be zero.",DescribeRole.Theorem),
            Node("threshold_obstruction","Distinguished-exponent threshold, including equality","Let m=k_d, A be the product of the other exponents, P the product of their successors and B=P-1-A. For at least three prime coordinates, A at least (m squared minus one)B minus (m minus one) gives an actual eigenvalue strictly between V-1 and V. The denominator-free trial has cell values m(m+1)B, (m-1)(m+1)B and -m(A+m-1), with zero mean. Energy minus norm squared factors as m B times ((m squared minus one)B-A-(m-1)) times (m A+(m squared minus one)B+m(m-1)). The weak threshold gives a nonpositive Rayleigh defect. At equality, a nonempty support containing d and another coordinate has trial action zero and nonzero trial value. Hence the trial is not a unit eigenvector; the Hermitian expansion still gives a strictly smaller positive eigenvalue. All prime permutations, m=1 and zero universal count are included.",DescribeRole.Theorem),
            Node("unit_exponent_obstruction","Unit exponent for every prime count at least three","The threshold theorem at m=1 applies for any distinguished unit coordinate and arbitrary positive remaining exponents. Thus the actual ideal graph has an eigenvalue in (V-1,V), and is not Laplacian integral. Taking every exponent equal to one gives the squarefree specialization; its exact application is checked transiently.",DescribeRole.Theorem),
            Node("reciprocal_obstruction","Reciprocal condition through the threshold","For m=k_d at least two, sum of 1/k_i over the other coordinates at most 1/m squared implies the full threshold. The product inequality converts the reciprocal hypothesis into A at least (m squared minus one)B minus (m-1). The theorem consumes the threshold result and repeats no Rayleigh proof. If every other k_i is at least m squared times (t-1), each reciprocal is at most 1 divided by that common bound; summing t-1 terms proves the hypothesis. This unbounded-coordinate application is checked transiently.",DescribeRole.Theorem),
            Node("two_prime_unit_integral","Sharp two-prime unit boundary","With precisely two distinct primes and one unit exponent, the complement is a star together with isolated universal vertices. A star on a center and A leaves has Laplacian eigenvalues among zero, one and A+1. Complement reflection therefore gives only integer actual eigenvalues, including the other exponent A=1. The higher-prime obstruction starts sharply at three prime factors.",DescribeRole.Theorem))));
    private static DocumentBlock Node(string name,string title,string prose,DescribeRole role)=>
        Describe.Lean(DescribeId.Create("nik-"+name.Replace('_','-').ToLowerInvariant()),
            DeclarationHandle.Create(Prefix+name),H(title),StatementSource.WithoutFormula(),
            AssessedProvenance.FromLiterature(Source),Blocks(Paragraph(Text(prose))),role);
}
